// [WSCoop] The rest only redraws the fog texture, which a headless (-nullrhi) server cannot do.
if (System::IsDedicatedServer() || WSDS::IsHeadlessHost())
    return;

    // [WSCoop] Map markers: elements that only exist on this machine's map (kept up to date by WSMapMarkers).
    void WSSetLocalElement(const FRegisteredWorldMapElement& Element)
    {
        const int Idx = FindElementIndex(Element.UniqueId);
        if (Idx < 0)
        {
            RegisteredMapElements.Add(Element);
            return;
        }
        const FRegisteredWorldMapElement& Old = RegisteredMapElements[Idx];
        const bool bSame = Old.ActorTransform.Location.Distance(Element.ActorTransform.Location) < 1.0
            && Old.Info.Generic.Name.ToString() == Element.Info.Generic.Name.ToString()
            && f"{Old.Info.Generic.IconColor}" == f"{Element.Info.Generic.IconColor}";
        RegisteredMapElements[Idx] = Element;
        RegisteredMapElements[Idx].bIsDirty = !bSame;
    }

    // [WSCoop]
    void WSRemoveLocalElement(FName UniqueId)
    {
        const int Idx = FindElementIndex(UniqueId);
        if (Idx >= 0)
            RegisteredMapElements.RemoveAt(Idx);
    }

// [WSCoop] Headless (-nullrhi) servers have no canvas to draw into. Keep the saved discovery
// bookkeeping (bitmask), skip only the drawing.
if (FogRenderTarget == nullptr)
    return;
const bool bCanDraw = !System::IsDedicatedServer() && !WSDS::IsHeadlessHost();
if (bCanDraw)
    Rendering::BeginDrawCanvasToRenderTarget(FogRenderTarget, Canvas, RenderTargetSize, Context);
if (Canvas == nullptr)
    RenderTargetSize = FVector2D(FogRenderTarget.SizeX, FogRenderTarget.SizeY);
